import java.util.Arrays;
import java.util.Comparator;
import java.util.Objects;

class MergeSort {

    private static final int INSERTION_SORT_THRESHOLD = 10;

    private MergeSort() {}

    public static void sort(int[] arr) {
        Objects.requireNonNull(arr, "arr must not be null");
        if (arr.length > 1) {
            mergeSort(arr, new int[arr.length], 0, 0, arr.length - 1);
        }
    }

    public static void sort(int[] arr, int fromIndex, int toIndex) {
        Objects.requireNonNull(arr, "arr must not be null");
        validateRange(arr.length, fromIndex, toIndex);
        if (toIndex - fromIndex > 1) {
            mergeSort(arr, new int[toIndex - fromIndex], fromIndex, fromIndex, toIndex - 1);
        }
    }

    private static void mergeSort(int[] arr, int[] temp, int offset, int left, int right) {
        if (right - left < INSERTION_SORT_THRESHOLD) {
            insertionSort(arr, left, right);
            return;
        }
        int mid = left + (right - left) / 2;
        mergeSort(arr, temp, offset, left, mid);
        mergeSort(arr, temp, offset, mid + 1, right);
        merge(arr, temp, offset, left, mid, right);
    }

    private static void insertionSort(int[] arr, int left, int right) {
        for (int i = left + 1; i <= right; i++) {
            int key = arr[i];
            int j = i - 1;
            while (j >= left && arr[j] > key) {
                arr[j + 1] = arr[j--];
            }
            arr[j + 1] = key;
        }
    }

    private static void merge(int[] arr, int[] temp, int offset, int left, int mid, int right) {
        for (int i = left; i <= right; i++) {
            temp[i - offset] = arr[i];
        }
        int i = left, j = mid + 1, k = left;
        while (i <= mid && j <= right) {
            if (temp[i - offset] <= temp[j - offset]) {
                arr[k++] = temp[i++ - offset];
            } else {
                arr[k++] = temp[j++ - offset];
            }
        }
        while (i <= mid) {
            arr[k++] = temp[i++ - offset];
        }
    }

    public static <T extends Comparable<T>> void sort(T[] arr) {
        Objects.requireNonNull(arr, "arr must not be null");
        sort(arr, Comparator.naturalOrder());
    }

    public static <T> void sort(T[] arr, Comparator<T> comparator) {
        Objects.requireNonNull(arr, "arr must not be null");
        Objects.requireNonNull(comparator, "comparator must not be null");
        if (arr.length > 1) {
            @SuppressWarnings("unchecked")
            T[] temp = (T[]) new Object[arr.length];
            mergeSort(arr, temp, comparator, 0, 0, arr.length - 1);
        }
    }

    public static <T extends Comparable<T>> void sort(T[] arr, int fromIndex, int toIndex) {
        Objects.requireNonNull(arr, "arr must not be null");
        sort(arr, fromIndex, toIndex, Comparator.naturalOrder());
    }

    public static <T> void sort(T[] arr, int fromIndex, int toIndex, Comparator<T> comparator) {
        Objects.requireNonNull(arr, "arr must not be null");
        Objects.requireNonNull(comparator, "comparator must not be null");
        validateRange(arr.length, fromIndex, toIndex);
        if (toIndex - fromIndex > 1) {
            @SuppressWarnings("unchecked")
            T[] temp = (T[]) new Object[toIndex - fromIndex];
            mergeSort(arr, temp, comparator, fromIndex, fromIndex, toIndex - 1);
        }
    }

    private static <T> void mergeSort(T[] arr, T[] temp, Comparator<T> comparator, int offset, int left, int right) {
        if (right - left < INSERTION_SORT_THRESHOLD) {
            insertionSort(arr, comparator, left, right);
            return;
        }
        int mid = left + (right - left) / 2;
        mergeSort(arr, temp, comparator, offset, left, mid);
        mergeSort(arr, temp, comparator, offset, mid + 1, right);
        merge(arr, temp, comparator, offset, left, mid, right);
    }

    private static <T> void insertionSort(T[] arr, Comparator<T> comparator, int left, int right) {
        for (int i = left + 1; i <= right; i++) {
            T key = arr[i];
            int j = i - 1;
            while (j >= left && comparator.compare(arr[j], key) > 0) {
                arr[j + 1] = arr[j--];
            }
            arr[j + 1] = key;
        }
    }

    private static <T> void merge(T[] arr, T[] temp, Comparator<T> comparator, int offset, int left, int mid, int right) {
        for (int i = left; i <= right; i++) {
            temp[i - offset] = arr[i];
        }
        int i = left, j = mid + 1, k = left;
        while (i <= mid && j <= right) {
            if (comparator.compare(temp[i - offset], temp[j - offset]) <= 0) {
                arr[k++] = temp[i++ - offset];
            } else {
                arr[k++] = temp[j++ - offset];
            }
        }
        while (i <= mid) {
            arr[k++] = temp[i++ - offset];
        }
    }

    private static void validateRange(int length, int fromIndex, int toIndex) {
        if (fromIndex < 0 || toIndex > length) {
            throw new ArrayIndexOutOfBoundsException(
                "Range [" + fromIndex + ", " + toIndex + ") out of bounds for length " + length);
        }
        if (fromIndex > toIndex) {
            throw new IllegalArgumentException("fromIndex " + fromIndex + " > toIndex " + toIndex);
        }
    }

    public static void main(String[] args) {
        int[] ints = {38, 27, 43, 10, 5, 1, 9, 3};
        sort(ints);
        System.out.println(Arrays.toString(ints));

        String[] words = {"banana", "apple", "cherry", "date"};
        sort(words);
        System.out.println(Arrays.toString(words));

        Integer[] nums = {5, 3, 8, 1, 9, 2};
        sort(nums, Comparator.reverseOrder());
        System.out.println(Arrays.toString(nums));

        int[] partial = {9, 5, 1, 7, 3, 8, 2};
        sort(partial, 2, 5);
        System.out.println(Arrays.toString(partial));
    }
}

